class Solution {
public:
    int countDaysTogether(std::string arriveAlice, std::string leaveAlice, std::string arriveBob, std::string leaveBob) {
        std::vector<int> days = {31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31};
        auto toDay = [&](const std::string& s) {
            int m = std::stoi(s.substr(0, 2));
            int d = std::stoi(s.substr(3, 2));
            int total = d;
            for (int i = 0; i < m - 1; i++) total += days[i];
            return total;
        };

        int startA = toDay(arriveAlice), endA = toDay(leaveAlice);
        int startB = toDay(arriveBob), endB = toDay(leaveBob);
        int overlapStart = std::max(startA, startB);
        int overlapEnd = std::min(endA, endB);
        return std::max(0, overlapEnd - overlapStart + 1);
    }
};

class Solution {
    public int countDaysTogether(String arriveAlice, String leaveAlice, String arriveBob, String leaveBob) {
        int[] days = {31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31};
        int startA = toDay(arriveAlice, days), endA = toDay(leaveAlice, days);
        int startB = toDay(arriveBob, days), endB = toDay(leaveBob, days);
        int overlapStart = Math.max(startA, startB);
        int overlapEnd = Math.min(endA, endB);
        return Math.max(0, overlapEnd - overlapStart + 1);
    }

    private int toDay(String s, int[] days) {
        int m = Integer.parseInt(s.substring(0, 2));
        int d = Integer.parseInt(s.substring(3, 5));
        int total = d;
        for (int i = 0; i < m - 1; i++) total += days[i];
        return total;
    }
}

